ALTER TABLE "campaign_observations" DROP CONSTRAINT "campaign_observations_event_type_check";--> statement-breakpoint
ALTER TABLE "campaign_observations" ADD CONSTRAINT "campaign_observations_approved_variant_check" CHECK ("campaign_observations"."event_type" <> 'approved_variant' OR ("campaign_observations"."outcome" = 'verified' AND "campaign_observations"."attribution" = 'unknown' AND "campaign_observations"."quantity" = 0 AND "campaign_observations"."visible_message_id" IS NOT NULL AND "campaign_observations"."variant_id" ~ '^[A-Fa-f0-9]{64}$' AND "campaign_observations"."note" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "campaign_observations" ADD CONSTRAINT "campaign_observations_event_type_check" CHECK ("campaign_observations"."event_type" IN ('approved_variant', 'sent', 'delivered', 'bounce', 'reply', 'qualified_reply', 'opt_out', 'booked', 'attended', 'follow_up', 'close_out', 'response_check'));